module uart_tx(
  input        clk,
  input        rst,
  input        tx_start,
  input  [7:0] tx_data,
  output reg   tx_serial,
  output reg   tx_busy,
  output reg   tx_done
);

  localparam [2:0] ST_IDLE  = 3'b000;
  localparam [2:0] ST_START = 3'b001;
  localparam [2:0] ST_DATA  = 3'b010;
  localparam [2:0] ST_STOP  = 3'b011;
  localparam [2:0] ST_DONE  = 3'b100;

  reg [2:0] state;
  reg [7:0] clk_count;
  reg [7:0] tx_shift;
  reg [2:0] bit_index;

  /*
   * Recovered baud terminal comparator.
   * This is not a full equality comparator; it is the minimized terminal
   * condition synthesized in the gate netlist.  Starting from zero it first
   * becomes true at clk_count == 8'd86.
   */
  wire baud_tick;
  assign baud_tick = clk_count[7] |
                    (clk_count[6] &
                    (clk_count[5] |
                    (clk_count[4] &
                    (clk_count[3] | (clk_count[1] & clk_count[2])))));

  always @(posedge clk) begin
    /*
     * State machine:
     *   IDLE  : line high, wait for tx_start
     *   START : transmit start bit
     *   DATA  : transmit 8 data bits, LSB first
     *   STOP  : transmit stop bit
     *   DONE  : one-cycle completion state
     */
    if (rst) begin
      state <= ST_IDLE;
    end else begin
      case (state)
        ST_IDLE: begin
          if (tx_start)
            state <= ST_START;
          else
            state <= ST_IDLE;
        end

        ST_START: begin
          if (baud_tick)
            state <= ST_DATA;
          else
            state <= ST_START;
        end

        ST_DATA: begin
          if (baud_tick && (bit_index == 3'd7))
            state <= ST_STOP;
          else
            state <= ST_DATA;
        end

        ST_STOP: begin
          if (baud_tick)
            state <= ST_DONE;
          else
            state <= ST_STOP;
        end

        ST_DONE: begin
          state <= ST_IDLE;
        end

        default: begin
          state <= ST_IDLE;
        end
      endcase
    end

    /*
     * Baud counter.
     * The synthesized machine holds the counter in any state with state[2]
     * asserted, increments during START/DATA/STOP until baud_tick, and clears
     * otherwise.
     */
    if (rst) begin
      clk_count <= 8'd0;
    end else if (state[2]) begin
      clk_count <= clk_count;
    end else if (((state == ST_START) || (state == ST_DATA) || (state == ST_STOP)) &&
                 !baud_tick) begin
      clk_count <= clk_count + 8'd1;
    end else begin
      clk_count <= 8'd0;
    end

    /*
     * Bit index for the DATA state.  It is cleared in IDLE/reset, held in
     * START/STOP/DONE, and increments on each data-bit baud tick, wrapping
     * after bit 7.
     */
    if (rst) begin
      bit_index <= 3'd0;
    end else if (state == ST_IDLE) begin
      bit_index <= 3'd0;
    end else if ((state == ST_DATA) && baud_tick) begin
      bit_index <= bit_index + 3'd1;
    end else begin
      bit_index <= bit_index;
    end

    /*
     * Transmit data holding register.  The gate netlist does not clear this
     * register on reset; it only loads when a transfer is accepted in IDLE.
     */
    if (!rst && (state == ST_IDLE) && tx_start) begin
      tx_shift <= tx_data;
    end else begin
      tx_shift <= tx_shift;
    end

    /*
     * Busy flag.
     */
    if (rst) begin
      tx_busy <= 1'b0;
    end else if ((state == ST_IDLE) && tx_start) begin
      tx_busy <= 1'b1;
    end else if ((state == ST_STOP) && baud_tick) begin
      tx_busy <= 1'b0;
    end else if (state == ST_IDLE) begin
      tx_busy <= 1'b0;
    end else begin
      tx_busy <= tx_busy;
    end

    /*
     * Done pulse: asserted for the cycle after the stop-bit terminal count.
     */
    if (rst) begin
      tx_done <= 1'b0;
    end else begin
      tx_done <= (state == ST_STOP) && baud_tick;
    end

    /*
     * Serial output:
     *   reset/idle/stop : high
     *   start           : low
     *   data            : selected data bit, LSB first
     *   done/state[2]   : hold previous value
     */
    if (rst) begin
      tx_serial <= 1'b1;
    end else begin
      case (state)
        ST_IDLE:  tx_serial <= 1'b1;
        ST_START: tx_serial <= 1'b0;
        ST_DATA:  tx_serial <= tx_shift[bit_index];
        ST_STOP:  tx_serial <= 1'b1;
        ST_DONE:  tx_serial <= tx_serial;
        default:  tx_serial <= state[2] ? tx_serial : 1'b1;
      endcase
    end
  end

endmodule

